    // Translate an English UI string into the current language.
    inline juce::String tr (const juce::String& en)
    {
        const int l = current();
        if (l == EN)
            return en;
        const auto& t = table();
        const auto it = t.find (en.toStdString());
        if (it == t.end())
            return en;
        const int idx = l < EN ? l : l - 1;   // table has no EN column
        const char* s = it->second[(size_t) idx];
        return (s != nullptr && s[0] != 0) ? juce::String::fromUTF8 (s) : en;
    }

    // JUCE's toUpperCase() leaves accented letters alone in the "C" locale, so do the common ones by hand.
    inline juce::String upper (const juce::String& s)
    {
        juce::String out;
        for (auto p = s.getCharPointer(); ! p.isEmpty(); ++p)
        {
            juce::juce_wchar c = *p;
            if (c < 128)                                  c = (juce::juce_wchar) std::toupper ((int) c);
            else if (c >= 0xE0 && c <= 0xFE && c != 0xF7) c -= 0x20;                    // Latin-1 (\u00e0-\u00fe)
            else if (c == 0x105 || c == 0x107 || c == 0x119 || c == 0x15B) c -= 1;      // polish a, c, e, s with ogonek/acute
            else if (c == 0x142 || c == 0x144 || c == 0x17A || c == 0x17C) c -= 1;      // l-stroke, n, z-acute, z-dot
            out << juce::String::charToString (c);
        }
        return out;
    }

